import React from 'react';
import "./Hero.scss";
import HeroImage from "./hero_image.svg";

const Hero = () => {
    return (
        <section className={"hero"}>
            <img src={HeroImage} alt={"hero image"} />
            <div className={"hero-content"}>
                <h1>Relationz</h1>
                <h2>Helps you create reminders for your tasks, meetings or other important events so you don't forget anything and are not late!</h2>
            </div>
        </section>
    );
};

export default Hero;
